class Solution {
    long long countUpTo(long long x) {
        if (x < 10) return 0;
        string bound = to_string(x);
        long long result = 0;
        for (int len = 2; len <= (int)bound.size(); ++len) {
            string limit = len == (int)bound.size() ? bound : string(len, '9');
            long long memo[17][300];
            memset(memo, -1, sizeof(memo));
            function<long long(int,int,bool)> dfs = [&](int pos, int diff, bool tight) -> long long {
                if (pos == len) return diff == 0;
                long long &cached = memo[pos][diff + 145];
                if (!tight && cached != -1) return cached;
                int hi = tight ? limit[pos] - '0' : 9;
                long long ways = 0;
                for (int d = (pos == 0); d <= hi; ++d) {
                    int nd = diff + ((pos % 2 == 0) ? d : -d);
                    ways += dfs(pos + 1, nd, tight && d == hi);
                }
                if (!tight) cached = ways;
                return ways;
            };
            result += dfs(0, 0, true);
        }
        return result;
    }
public:
    long long countBalanced(long long low, long long high) {
        return countUpTo(high) - countUpTo(low - 1);
    }
};
